<?php if($canManage): ?><div class="modal fade" id="itemModal" tabindex="-1"><div class="modal-dialog modal-dialog-centered"><div class="modal-content"><form id="form"><div class="modal-header"><div><h5 class="modal-title" id="modalTitle">Ajouter</h5><small class="text-muted">Structure réelle de votre établissement.</small></div><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><input type="hidden" name="csrf" value="<?=htmlspecialchars($_SESSION['csrf'])?>"><input type="hidden" name="id" id="itemId"><div class="mb-3"><label class="form-label">Type *</label><select name="type" id="type" class="form-select" required><?php if($serviceEnabled): ?><option value="SERVICE"><?=htmlspecialchars($serviceSingular)?></option><?php endif; ?><?php if($unitEnabled): ?><option value="UNITE"><?=htmlspecialchars($unitSingular)?></option><?php endif; ?></select></div><div class="mb-3"><label class="form-label">Nom *</label><input name="nom" id="name" class="form-control" maxlength="150" required></div><div class="parent-box mb-3"><div class="form-check form-switch mb-2"><input type="hidden" name="has_parent" value="0"><input class="form-check-input" type="checkbox" name="has_parent" value="1" id="hasParent"><label class="form-check-label fw-semibold" for="hasParent">Cette structure a un parent</label></div><div id="parentWrap" class="d-none"><label class="form-label">Choisir le parent *</label><select name="parent_id" id="parent" class="form-select"></select></div><small class="text-muted">Si non coché : directement rattaché à l’établissement.</small></div><div class="mb-3"><label class="form-label">Capacité d’accueil</label><input type="number" min="0" name="capacite" id="capacity" class="form-control"><small class="text-muted">Nombre maximal de stagiaires simultanés.</small></div><div><label class="form-label">Description</label><textarea name="description" id="description" class="form-control" rows="3"></textarea></div></div><div class="modal-footer"><button type="button" class="btn btn-light border" data-bs-dismiss="modal">Annuler</button><button type="submit" class="btn btn-primary-stagia" id="saveBtn"><i class="bi bi-check-lg me-1"></i>Enregistrer</button></div></form></div></div></div><?php endif; ?>
<script>document.addEventListener('DOMContentLoaded',()=>{const BASE_URL='<?=BASE_URL?>',$=id=>document.getElementById(id),esc=STAGIA.escape,canManage=<?=$canManage?'true':'false'?>,CONFIG=<?=json_encode($cfg,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>;let items=[],parents=[],timer;const modal=canManage?new bootstrap.Modal($('itemModal')):null;const label=(t,p=false)=>CONFIG[t]?.[p?'label_plural':'label_singular']||t;function allowed(t){if(t==='SERVICE')return CONFIG.DEPARTEMENT?.actif?['DEPARTEMENT']:[];if(t==='UNITE'){const a=[];if(CONFIG.SERVICE?.actif)a.push('SERVICE');if(CONFIG.DEPARTEMENT?.actif)a.push('DEPARTEMENT');return a}return[]}function fillParents(selected=''){if(!canManage)return;const types=allowed($('type').value),list=parents.filter(x=>Number(x.actif)===1&&types.includes(x.type));$('parent').innerHTML='<option value="">Sélectionner...</option>'+list.map(x=>`<option value="${x.id}">${esc(label(x.type))} — ${esc(x.nom)}</option>`).join('');if(selected)$('parent').value=String(selected);$('hasParent').disabled=!list.length;if(!list.length)$('hasParent').checked=false;toggleParent()}function toggleParent(){if(!canManage)return;const show=$('hasParent').checked&&!$('hasParent').disabled;$('parentWrap').classList.toggle('d-none',!show);$('parent').required=show;if(!show)$('parent').value=''}async function load(){const q=new URLSearchParams({type:$('typeFilter').value||'SERVICE_UNITE'});if($('search').value.trim())q.set('search',$('search').value.trim());if($('status').value!=='')q.set('actif',$('status').value);try{const r=await STAGIA.request(BASE_URL+'/actions/espace-hopital/structure-list.php?'+q),d=r.data;items=d.items||[];parents=d.parents||[];$('kTotal').textContent=(d.kpi.services||0)+(d.kpi.units||0);$('kServices').textContent=d.kpi.services||0;$('kUnits').textContent=d.kpi.units||0;$('kActive').textContent=items.filter(x=>Number(x.actif)===1).length;$('rows').innerHTML=items.length?items.map(x=>`<tr><td><strong>${esc(x.code)}</strong></td><td><span class="badge bg-light text-dark border">${esc(label(x.type))}</span></td><td><strong>${esc(x.nom)}</strong>${x.description?`<small class="d-block text-muted">${esc(x.description)}</small>`:''}</td><td>${x.parent_nom?`<strong>${esc(x.parent_nom)}</strong><small class="d-block text-muted">${esc(label(x.parent_type))}</small>`:'<span class="text-muted">Établissement</span>'}</td><td>${x.capacite===null||x.capacite===''?'—':`<strong>${Number(x.capacite)}</strong>`}</td><td>${Number(x.actif)===1?'<span class="badge bg-success-subtle text-success">Actif</span>':'<span class="badge bg-secondary-subtle text-secondary">Inactif</span>'}</td><td class="text-end">${canManage?`<button class="btn btn-sm btn-outline-primary edit" data-id="${x.id}"><i class="bi bi-pencil"></i></button> <button class="btn btn-sm btn-outline-secondary toggle" data-id="${x.id}" data-next="${Number(x.actif)===1?0:1}"><i class="bi bi-${Number(x.actif)===1?'pause-circle':'play-circle'}"></i></button>`:'—'}</td></tr>`).join(''):'<tr><td colspan="7" class="text-center py-5 text-muted">Aucune structure.</td></tr>';document.querySelectorAll('.edit').forEach(b=>b.onclick=()=>edit(Number(b.dataset.id)));document.querySelectorAll('.toggle').forEach(b=>b.onclick=()=>toggle(Number(b.dataset.id),Number(b.dataset.next)))}catch(e){$('rows').innerHTML=`<tr><td colspan="7" class="text-center py-5 text-danger">${esc(e.message)}</td></tr>`}}if(canManage){$('type').onchange=()=>fillParents();$('hasParent').onchange=toggleParent;$('addBtn').onclick=()=>{$('form').reset();$('itemId').value='';$('type').disabled=false;fillParents();$('modalTitle').textContent='Ajouter';modal.show()};function edit(id){const x=items.find(v=>Number(v.id)===id);if(!x)return;$('form').reset();$('itemId').value=x.id;$('type').value=x.type;$('type').disabled=true;$('name').value=x.nom||'';$('capacity').value=x.capacite??'';$('description').value=x.description||'';$('hasParent').checked=!!x.parent_id;fillParents(x.parent_id||'');$('modalTitle').textContent='Modifier '+label(x.type);modal.show()}$('form').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.currentTarget);if($('type').disabled)fd.set('type',$('type').value);STAGIA.loading($('saveBtn'),true);try{const r=await STAGIA.post(BASE_URL+'/actions/espace-hopital/structure-save.php',fd);STAGIA.toast(r.message);modal.hide();await load()}catch(e){STAGIA.toast(e.message,'danger')}finally{STAGIA.loading($('saveBtn'),false)}};async function toggle(id,next){if(!STAGIA.confirm(next?'Réactiver cette structure ?':'Désactiver cette structure ?'))return;const fd=new FormData();fd.append('csrf','<?=$_SESSION['csrf']?>');fd.append('id',id);fd.append('actif',String(next));try{const r=await STAGIA.post(BASE_URL+'/actions/espace-hopital/structure-status.php',fd);STAGIA.toast(r.message);await load()}catch(e){STAGIA.toast(e.message,'danger')}}}$('search').oninput=()=>{clearTimeout(timer);timer=setTimeout(load,300)};$('typeFilter').onchange=load;$('status').onchange=load;load()});</script>
